templates.body:
index={{var:index}} sourcetype="XmlWinEventLog:Security" (EventCode=4720 OR EventCode=4722 OR EventCode=4728 OR EventCode=4732) earliest=-{{var:range}}
| table _time, host, EventCode, SubjectUserName, TargetUserName, MemberName, GroupName
| sort - _time

index={{var:index}} sourcetype="XmlWinEventLog:System" EventCode=7045 earliest=-{{var:range}}
| table _time, host, ServiceName, ImagePath, ServiceType, StartType, AccountName
| sort - _time

index={{var:index}} sourcetype="XmlWinEventLog:Microsoft-Windows-Windows Defender/Operational" (EventCode=5001 OR EventCode=5007 OR EventCode=5010 OR EventCode=5012) earliest=-{{var:range}}
| table _time, host, EventCode, Message
| sort - _time
